// 1. Ouvinte Global (Event Delegation)
document.addEventListener("click", function (e) {
  const card = e.target.closest(".card-equipamento");
  if (!card) return;

  // Extração de dados com limpeza (converte para número para facilitar cálculos)
  const dados = {
    host: card.getAttribute("data-hostname") || "Link de Internet",
    status: card.getAttribute("data-status"),
    latencia: parseFloat(card.getAttribute("data-latencia") || 0).toFixed(2),
    perda: parseFloat(card.getAttribute("data-perda") || 0).toFixed(1),
    sla: parseFloat(card.getAttribute("data-disponibilidade") || 0).toFixed(2)
  };

  criarModalTOP(dados);
});

function criarModalTOP(d) {
  const antigo = document.getElementById("modal-livre-global");
  if (antigo) antigo.remove();

  // --- LÓGICA DE INTELIGÊNCIA DO MODAL ---

  // Cores de Status
  const isUp = (d.status === "1" || d.status === "ON" || d.status === "UP");
  const corStatus = isUp ? "#28a745" : "#dc3545";
  const textoStatus = isUp ? "🌐 CONECTADO" : "🚨 DESCONECTADO";

  // Alerta de Latência (Amarelo > 100ms, Vermelho > 250ms)
  let corLatencia = "#3274D9"; // Azul padrão
  if (d.latencia > 100) corLatencia = "#f1c40f";
  if (d.latencia > 250) corLatencia = "#e74c3c";

  // Alerta de Perda (Qualquer perda > 0 já sinaliza em laranja/vermelho)
  const corPerda = d.perda > 0 ? "#ff9830" : "#aaa";

  const modal = document.createElement("div");
  modal.id = "modal-livre-global";

  modal.innerHTML = `
    <div id="modal-header" style="cursor:grab; background:#2c3235; padding:12px; color:#efefef; display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #444;">
        <span style="font-size: 12px; font-weight: bold; opacity: 0.7;">📍 MONITORAMENTO PRO</span>
        <span id="fecharModal" style="font-size:20px; cursor:pointer; line-height:1;">&times;</span>
    </div>

    <div style="padding:25px; color:#d8d9da; background: linear-gradient(180deg, #1e1e20 0%, #18181a 100%);">
        <div style="text-align:center; margin-bottom: 25px;">
            <h2 style="margin:0; font-size: 20px; color: #fff;">${d.host}</h2>
            <div style="display:inline-block; margin-top:8px; padding:4px 12px; border-radius:20px; background: ${corStatus}22; border: 1px solid ${corStatus}; color: ${corStatus}; font-size: 11px; font-weight: bold;">
                ${textoStatus}
            </div>
        </div>

        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
            <div style="background: #252529; padding: 15px; border-radius: 10px; border-left: 4px solid ${corLatencia};">
                <span style="font-size: 10px; color: #888; text-transform: uppercase;">Latência</span><br>
                <b style="font-size: 22px; color: ${corLatencia};">${d.latencia} <small style="font-size:10px;">ms</small></b>
            </div>

            <div style="background: #252529; padding: 15px; border-radius: 10px; border-left: 4px solid ${corPerda};">
                <span style="font-size: 10px; color: #888; text-transform: uppercase;">Perda</span><br>
                <b style="font-size: 22px; color: ${corPerda};">${d.perda} <small style="font-size:10px;">%</small></b>
            </div>

            <div style="background: #252529; padding: 15px; border-radius: 10px; grid-column: span 2; display: flex; justify-content: space-between; align-items: center;">
                <div>
                   <span style="font-size: 10px; color: #888; text-transform: uppercase;">Disponibilidade (SLA)</span><br>
                   <b style="font-size: 24px; color: #eee;">99.9%</b>
                </div>
                <div style="width: 50px; height: 50px; border-radius: 50%; border: 3px solid #333; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: bold; color: #28a745;">
                    OK
                </div>
            </div>
        </div>

        <div style="margin-top: 20px; text-align: center; font-size: 10px; color: #555;">
            Sincronizado com Zabbix API via Token
        </div>
    </div>
  `;

  // Estilo da Janela
  Object.assign(modal.style, {
    position: "fixed", top: "15%", left: "35%", width: "380px",
    backgroundColor: "#1e1e20", borderRadius: "12px", zIndex: "10000",
    boxShadow: "0 20px 50px rgba(0,0,0,0.8)", border: "1px solid #333",
    fontFamily: "'Inter', sans-serif", overflow: "hidden"
  });

  document.body.appendChild(modal);
  modal.querySelector("#fecharModal").onclick = () => modal.remove();
  tornarArrastavel(modal);
}

// Motor de Arrasto Robusto
function tornarArrastavel(elmnt) {
  let pos1 = 0, pos2 = 0, pos3 = 0, pos4 = 0;
  const header = elmnt.querySelector("#modal-header");
  header.onmousedown = dragMouseDown;

  function dragMouseDown(e) {
    e.preventDefault();
    pos3 = e.clientX;
    pos4 = e.clientY;
    document.onmouseup = closeDragElement;
    document.onmousemove = elementDrag;
    header.style.cursor = "grabbing";
  }

  function elementDrag(e) {
    e.preventDefault();
    pos1 = pos3 - e.clientX;
    pos2 = pos4 - e.clientY;
    pos3 = e.clientX;
    pos4 = e.clientY;
    elmnt.style.top = (elmnt.offsetTop - pos2) + "px";
    elmnt.style.left = (elmnt.offsetLeft - pos1) + "px";
  }

  function closeDragElement() {
    document.onmouseup = null;
    document.onmousemove = null;
    header.style.cursor = "grab";
  }
}

options.styles:
.card-equipamento {
    display: inline-flex;
    align-items: center;
    padding: 12px 20px;
    border-radius: 8px;
    cursor: pointer;
    font-weight: bold;
    color: white;
    margin: 5px;
    background-color: #555555; 
    box-shadow: 0 4px 6px rgba(0,0,0,0.3);
    transition: transform 0.2s;
}

/* 🟢 Cores baseadas no data-status que configuramos no JS */
div[data-status="1"] { background-color: #28a745 !important; }
div[data-status="0"] { background-color: #dc3545 !important; }

/* A Bolinha de Status */
.luz-status {
    width: 12px;
    height: 12px;
    background-color: white;
    border-radius: 50%;
    margin-right: 12px;
    position: relative;
    display: inline-block;
}

/* Efeito de Pulso para Internet OK (apenas quando o status for 1) */
div[data-status="1"] .luz-status::after {
    content: '';
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    background-color: white;
    border-radius: 50%;
    animation: pulsar 2s infinite;
}

@keyframes pulsar {
    0% { transform: scale(1); opacity: 0.8; }
    100% { transform: scale(2.5); opacity: 0; }
}

.nome-host { font-size: 14px; text-transform: uppercase; }
